/** Build the pinned HyperFrames runtime; package assembly owns its destinations. */
import { readdir, rm } from "node:fs/promises";
import { resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { execFileSync } from "node:child_process";
import { ensureCachedRuntime } from "./runtime-cache.mjs";

const repository = fileURLToPath(new URL("../", import.meta.url));
let pending;

/** Source-tree outputs regenerated by the pinned build, relative to HyperFrames. */
export const RUNTIME_GENERATED_SOURCES = Object.freeze([
  "packages/core/src/generated/runtime-inline.ts",
  "packages/core/src/generated/position-edits-render-inline.ts",
  "packages/core/src/generated/audio-fx-runtime-inline.ts",
  "packages/core/src/generated/svg-selector-aliases-inline.ts",
  "packages/producer/src/generated/hf-early-stub-inline.ts",
  "packages/core/src/fonts/fontData.generated.ts",
  "packages/producer/src/services/fontData.generated.ts",
]);

async function compileRuntime() {
  const cwd = resolve(repository, "vendor/hyperframes");
  const run = (args) => execFileSync("bun", args, { cwd, stdio: "inherit" });
  run(["install", "--frozen-lockfile", "--ignore-scripts"]);
  // Upstream skips existing embedded fonts; regenerate them from the locked font packages.
  for (const path of RUNTIME_GENERATED_SOURCES.filter((path) =>
    path.endsWith("/fontData.generated.ts"),
  ))
    await rm(resolve(cwd, path), { force: true });
  // Upstream's CLI keeps old chunks; clean owned outputs before every rebuild.
  for (const entry of await readdir(resolve(cwd, "packages"), {
    withFileTypes: true,
  })) {
    if (entry.isDirectory())
      await rm(resolve(cwd, "packages", entry.name, "dist"), {
        recursive: true,
        force: true,
      });
  }
  run(["run", "build:local-studio"]);
}

async function ensure(force) {
  return ensureCachedRuntime({
    inputs: [
      resolve(repository, "vendor/hyperframes"),
      resolve(repository, "packages/studio-core/src/original/ui"),
      resolve(repository, "package.json"),
      resolve(repository, "package-lock.json"),
      fileURLToPath(import.meta.url),
      fileURLToPath(new URL("./runtime-cache.mjs", import.meta.url)),
    ],
    excludedInputs: RUNTIME_GENERATED_SOURCES.map((path) =>
      resolve(repository, "vendor/hyperframes", path),
    ),
    environment: {
      node: process.versions.node,
      bun: execFileSync("bun", ["--version"], { encoding: "utf8" }).trim(),
      platform: process.platform,
      arch: process.arch,
      runtimeVariant: process.env.SANDBOX_RUNTIME_VARIANT ?? "",
      runtimeBuildId: process.env.HYPERFRAME_RUNTIME_BUILD_ID ?? "",
      runtimeVersion: process.env.HYPERFRAME_RUNTIME_VERSION ?? "",
    },
    directory: resolve(repository, "vendor/hyperframes/packages/cli/dist"),
    requiredFiles: ["cli.js", "studio/index.html"],
    stamp: resolve(repository, ".runtime/hyperframes-build.json"),
    build: compileRuntime,
    force,
  });
}

/** Ensure generated runtime files match current source and build tools.
 * @returns {Promise<boolean>} Whether this invocation rebuilt HyperFrames.
 */
export function ensureRuntimeBuild() {
  pending ??= ensure(false).finally(() => {
    pending = undefined;
  });
  return pending;
}

/** Rebuild HyperFrames even when its cache matches the source.
 * @returns {Promise<boolean>} True after a successful rebuild.
 */
export async function buildRuntime() {
  if (pending) await pending;
  pending = ensure(true).finally(() => {
    pending = undefined;
  });
  return pending;
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(resolve(process.argv[1])).href
)
  await buildRuntime();
